            new ReportExample("cơ quan chủ quản dùng Arial đỏ cỡ 14.","CƠ QUAN CHỦ QUẢN; Times New Roman, đen, cỡ 12–13, đứng, không đậm; giữ nội dung, căn đoạn và cỡ đang hợp lệ.")),
        new("C23","Nơi nhận tại ô 9b",CapabilityMode.Reviewable,"Nhà nước, nhãn Nơi nhận và dòng Lưu cùng vùng XML đã nhận diện",
            "NĐ30 PL I.I.4 và II.9.d: nhãn cỡ 12 nghiêng đậm; danh sách cỡ 11 đứng, có gạch đầu dòng, cuối dòng ;, dòng Lưu kết thúc bằng chấm. Không áp quy tắc dấu đơn/thứ tự mục thân bài cho danh sách này. Chưa đo đủ vị trí lề/hàng, không đoán đơn vị nhận hoặc số bản lưu.",
            new ReportExample("Nơi nhận: cỡ 14 đứng; một dòng ghi Đơn vị mẫu.","Nhãn cỡ 12 nghiêng đậm; danh sách cỡ 11 đứng; sửa dòng thành - Đơn vị mẫu; khi đã xác minh có dòng Lưu cuối khối.")),
        new("C24","Viết hoa tên loại văn bản",CapabilityMode.Reviewable,"Nhà nước, tên loại thuộc danh mục hành chính/bổ sung đã nhận diện chắc trong khối đầu trang",
            "Theo NĐ30 PL I.II.5.b: tên loại in hoa. 27 tên theo PL III.I và Báo cáo đề xuất/BCĐX theo yêu cầu người dùng; không nhận tên bản sao theo mẫu văn bản gốc. Chỉ đổi hoa/thường tên chính xác, có proof chữ thuần và dữ liệu định dạng đủ chắc; chấp nhận cỡ hợp lệ khác nhau và đối chiếu từng ký tự sau viết hoa. Ví dụ Báo cáo có chữ cỡ13/14 và gạch chân → BÁO CÁO, giữ từng cỡ13/14 và gạch chân. Giữ phông/màu/kiểu/căn đoạn chưa chọn sửa; nếu chọn kèm phông/cỡ thì chỉ đổi thuộc tính đã duyệt. Giữ khoảng trắng ngoài tên, trích yếu nhiều đoạn, phông và căn đoạn. Không suy đoán tên loại từ nội dung, không tự viết thường trích yếu hoặc áp cho Công văn/V/v, bảng/field/drawing/vùng chưa rõ. Có thể chọn chung sửa phông, một Undo/rollback.",
            new ReportExample("Báo cáo","BÁO CÁO")),
        new("C25","Khoảng trắng cuối đoạn sau dấu câu",CapabilityMode.Reviewable,"Cả ba chế độ, đoạn chữ thuần có kết thúc rõ bằng .?! hoặc ;",
            "Xóa dấu cách ASCII sau dấu kết câu hoặc chấm phẩy cuối đoạn, giữ dấu kết đoạn/ô, dấu câu, chữ và khoảng trước chưa chọn. Cần hai từ rõ bên trái; bỏ qua số/ngày, mã/đường dẫn/viết tắt, khoảng không ngắt, tab, ô trống, đoạn chưa kết câu và vùng XML chưa chắc. Có thể sửa chung các nhóm chữ/phông đủ điều kiện; cần duyệt.",
            new ReportExample("Đã hoàn thành.   ","Đã hoàn thành.")),
        new("C26","Phông/cỡ chữ nội dung",CapabilityMode.Reviewable,"Nhà nước, văn xuôi thường trong văn bản có tên loại, sau Kính gửi hoặc hai đoạn mở đầu có proof bố cục/chữ thường, trước chữ ký/Nơi nhận",
            "NĐ30 PL I.I.4 và II.6.e: Times New Roman, đen, cỡ 13–14, đứng. Chỉ đoạn chữ thuần đã đối chiếu XML, không danh sách/mục/bảng/field; từ .64 giữ đậm/nghiêng từng glyph đã đọc chắc, chỉ sửa phông/màu/cỡ; cỡ sai về13 và giữ từng cỡ13/14 đúng. Giữ chữ, đậm/nghiêng, gạch chân, căn/thụt và spacing; đối chiếu từng ký tự sau lưu/Line, một Undo và rollback. C26 không tự sửa căn/giãn đoạn (C27/C28/C29 có phạm vi riêng) hoặc toàn bộ thân bài; vùng chưa đủ bằng chứng bỏ qua, không kết luận đúng toàn bộ.",
            new ReportExample("Đoạn nội dung thông thường có chữ Arial đỏ cỡ12 và chữ cỡ14.","Sau duyệt: Times New Roman đen, cỡ12 về13, giữ chữ cỡ14 và nguyên văn/gạch chân/căn đoạn.")),
        new("C27","Căn/thụt đầu dòng nội dung",CapabilityMode.Reviewable,"Nhà nước, văn xuôi thường trong phạm vi C26, không thụt cả đoạn/danh sách/bảng; có thể có từ nhấn mạnh xen chữ thường đứng",
            "NĐ30 PL I.II.6.e: căn đều hai lề, đầu dòng lùi1cm hoặc1,27cm. Giữ mức đang đúng; sai đề xuất1,27cm. Chỉ sửa thuộc tính đã duyệt; đoạn có từ nhấn mạnh xen chữ thường đứng vẫn giữ từng đậm/nghiêng; giữ nguyên văn/phông/cỡ/gạch chân, khoảng đoạn và giãn dòng; đối chiếu sau lưu/Line, sửa chung chữ/phông, một Undo/rollback. Cần XML và quan sát đoạn/phông chắc; không sửa khoảng trắng thủ công đầu dòng, thụt cả đoạn, hanging, bảng/mục/chữ ký hoặc toàn bộ thân bài.",
            new ReportExample("Đoạn văn xuôi thường căn trái, dòng đầu thụt0cm.","Sau duyệt: căn đều, dòng đầu1,27cm; giữ phông/cỡ, khoảng đoạn và giãn dòng chưa chọn.")),
        new("C28","Khoảng cách giữa các đoạn",CapabilityMode.Reviewable,"Nhà nước, hai đoạn văn xuôi thường liền nhau cùng trang, XML/ngữ cảnh/spacing chắc",
            "NĐ30 PL I.II.6.e: giữa các đoạn tối thiểu6pt. Xét cả sau đoạn trước và trước đoạn sau; chỉ khi tổng hai khoảng còn dưới6pt mới đề xuất sau đoạn trước6pt, giữ trước đoạn sau. Không kết luận sai từ After đơn lẻ; tổng đủ6pt nhưng có thể bị gộp giữ ngoài phạm vi chờ đo. Bỏ qua khác trang, đoạn trống/mục/bảng xen giữa, contextual/auto spacing, keep/page break/grid, đơn vị dòng kế thừa và bố cục đặc biệt hoặc vùng chưa chắc; nêu riêng phạm vi cần kiểm thủ công. Đoạn có từ nhấn mạnh xen chữ thường đứng vẫn giữ từng kiểu. Sửa riêng/chung giữ phông/cỡ/căn/thụt/giãn dòng chưa chọn, kiểm lại cặp đoạn và XML sau lưu/Line, một Undo/rollback.",
            new ReportExample("Hai đoạn văn xuôi liền nhau cùng trang: sau đoạn trước0pt, trước đoạn sau0pt.","Sau duyệt: sau đoạn trước6pt; giữ trước đoạn sau, giãn dòng và các phần chưa chọn.")),
        new("C29","Giãn dòng nội dung",CapabilityMode.Reviewable,"Nhà nước, văn xuôi thường có Word Double hoặc Multiple ngoài1–1,5 dòng chắc chắn",
            "NĐ30 PL I.II.6.e: dòng đơn đến1,5lines. Nhận Single/1,5 và Multiple1–1,5 đang đúng. Double hoặc Multiple ngoài khoảng đề xuất Single; chỉ ghi LineSpacingRule, không gán pt biến chế độ thành Exactly. Exactly/AtLeast chưa có số đo tương đương, grid/đơn vị dòng/bố cục đặc biệt hoặc ngữ cảnh chưa chắc giữ ngoài quyền sửa; thông báo phần chưa kiểm, không báo lỗi chỉ từ tên chế độ. Đoạn có từ nhấn mạnh xen chữ thường đứng vẫn giữ từng kiểu. Giữ khoảng đoạn, căn/thụt và phông/cỡ chưa chọn; hậu kiểm XML/thuộc tính/glyph sau lưu/Line, sửa riêng/chung, một Undo/rollback.",
            new ReportExample("Đoạn văn xuôi thường giãn dòng Double (2 dòng).","Sau duyệt: Single (dòng đơn); giữ khoảng đoạn, căn/thụt, chữ/phông/cỡ chưa chọn.")),
        new("C30","Khoảng trắng quanh ngoặc kép",CapabilityMode.Reviewable,"Cả ba chế độ, cặp ngoặc kép cong hoặc thẳng cân bằng, không trộn/lồng, chứa lời văn rõ",
            "Xóa dấu cách ASCII ngay bên trong ngoặc kép cong hoặc thẳng; thêm trước dấu mở khi hai từ trước/trong và biên sau rõ; giữ nguyên dấu ngoặc, chữ, kiểu/cỡ và khoảng cách chưa chọn. Có thể chọn từng phía hoặc sửa chung lỗi chữ/phông/đường kẻ qua luồng đã xác minh. B02 sau .64 thêm một dấu cách sau quote đóng khi hai từ trước, ít nhất hai từ chữ trong và hai từ sau rõ, từ ngay sau thường; dùng đúng mốc quote và giữ mép trong/phần chưa chọn. Không áp nhánh thêm sau cho câu có dấu kết trong quote, mã hoặc ranh giới chưa rõ. Từ B05 giữ một dấu .?! gắn cuối câu trích dẫn có từ trái rõ; không đổi dấu/khoảng trước dấu hoặc suy nghĩa. Không đổi loại ngoặc hoặc nội dung trích dẫn; bỏ qua cặp rỗng/ô trống, chữ số/mã, toàn hoa, một từ, lồng/thiếu/trộn dấu, ngoặc đơn kiểu khác, tab/NBSP/control và vùng XML chưa chắc. Căn cứ là quy tắc ứng dụng, không gán thành quy định riêng của NĐ30.",
            new ReportExample("Theo mẫu\" nội dung \"đã duyệt.","Theo mẫu \"nội dung\" đã duyệt.")),
        new("C31","Khối ký và chỗ ký tay",CapabilityMode.Reviewable,"Nhà nước, bảng cuối văn bản có Nơi nhận/Lưu bên trái, chức vụ và họ tên rõ bên phải",
            "NĐ30 PL I.I.4 và II.7.đ (PDF21,26–27): Times New Roman, đen, cỡ13–14, đứng, đậm. Chỉ sửa thuộc tính sai; giữ từng cỡ đúng, họ tên/cấp bậc, chữ hoa/thường, gạch chân, căn/thụt/khoảng đoạn, ảnh chữ ký và dấu. Cần XML và quan sát font chắc; hỗ trợ ngắt dòng mềm ở chức vụ. Không suy ra thẩm quyền/người ký hoặc đổi nội dung/căn khối. Bảng lồng/gộp, placeholder, danh sách tự động, phụ lục phía sau hoặc khối chưa chắc nằm ngoài phạm vi; không báo sai từ dữ liệu chưa biết. Sửa phông riêng/chung nhóm khác qua checkpoint, hậu kiểm, một Undo/rollback. Có lệnh chủ động Kiểm tra → Chừa chỗ ký tay (80 pt) theo yêu cầu người dùng: đo khoảng XPS, bổ sung phần thiếu khi vùng giữa còn trống và đủ chỗ trên trang, giữ khoảng đã đủ và Enter/chữ/phông; một Undo riêng.80pt không phải yêu cầu bắt buộc của NĐ30. Không cần ảnh chữ ký; chưa có chứng cứ chạy Office2021 cho bước mới.",
            new ReportExample("TRƯỞNG PHÒNG hoặc Đại tá Nguyễn Văn An dùng Arial đỏ, cỡ12, nghiêng, không đậm.","Sau duyệt: Times New Roman đen, cỡ12 về13, đứng, đậm; giữ cỡ13/14 đang đúng, tên/cấp bậc và bố cục.")),
        new("C32","Khổ giấy và lề trang",CapabilityMode.Reviewable,"Nhà nước, một section dọc thông thường; đầu/cuối trang không có hoặc đã chứng minh thực sự trống; chưa có ảnh/Shape hoặc bố cục đặc biệt",
            "NĐ30 PL I.I.1–3 (PDF21): A4, trên/dưới20–25, trái30–35, phải15–20mm. Đặt giấy sai vềA4; chỉ lề ngoài khoảng về biên gần nhất, giữ chính xác lề đúng. Candidate chỉ đổi thuộc tính pgSz/pgMar, xác minh toàn bộ chữ/bảng/kiểu và mọi phần ZIP khác. Bảng phải vừa vùng mới, không gộp/lồng/nổi; hình/field/control/tab, nhiều section, lề đối xứng/gáy/đóng sách/cột/khác hướng giữ thủ công. Sửa trang trước, quét/đo lại nhóm đã chọn theo prefix/chữ thật, không dùng CP/toạ độ cũ. Hậu kiểm khổ trên XPS và chữ/phông/cỡ/căn-khoảng đoạn/Line sau cả lượt lưu-mở; một tổng tiến độ, một Undo/rollback. Đợt19 nhận header/footer thực sự trống sau đối chiếu reference/quan hệ/style/default; không coi dấu cách, field, nét trang trí hoặc style chưa rõ là trống. Giữ nguyên mọi phần đầu/cuối trang và quan hệ; hậu kiểm XML cùng toàn bộ hộp chữ/mực/nét XPS phải nằm trong vùng nội dung mới ngay sau đổi trang và cuối lượt, nếu phần trống chiếm chỗ đẩy nội dung ra lề thì phục hồi. Số trang có phạm vi C33 riêng; chưa tự sửa ngoại lệ; chưa có runtime Office2021 cho nhóm mới.",
            new ReportExample("Văn bản dọc Letter, lề trên10/dưới22/trái20/phải15mm, bảng vừa vùngA4 mới.","Sau duyệt: A4; lề20/22/30/15mm. Giữ lề22/15 đang đúng, chữ/bảng/kiểu; đo lại các nhóm chọn kèm.")),
        new("C33","Số trang và trường PAGE",CapabilityMode.Reviewable,"Nhà nước, một section dọc, header trống hoặc chỉ PAGE đã nhận diện chắc",
            "NĐ30 PL I.I.4 và I.7 (PDF21): Times New Roman đen, sốẢRập từ1, cỡ13–14, đứng, giữa lề trên, không hiện trang đầu. Từ hai trang thiếu số mới đề xuất; một trang không có header không bị báo thiếu. Tạo/sửa PAGE đúng vai trò; giữ cỡ13–14 hợp lệ, đậm/gạch chân và footer, kể cả footer trước đây hiện trang đầu. Header có nội dung/logo, trường khoá, font/kiểu chưa đọc chắc, nhiều section/odd-even/gáy/đối xứng giữ thủ công hoặc ngoài phạm vi. Đợt18 cho chuyển footer chỉ chứa PAGE nguồn rõ: một section, sốẢRập bắt đầu1, từ1–10000trang, phông/màu/cỡ biết chắc, không nhãn/chữ thêm/tab/trang trí; Đợt20 ghép các cụm chữ số liền nhau cùng dòng nền, không chồng, đúng từng kiểu; loại toàn cụm nguồn duy nhất khỏi snapshot trước sửa và kiểm số dư cả khi XPS tách cụm. Ghép đúng duy nhất số nguồn hiển thị trọn trong lề dưới mỗi trang. Chỉ bỏ reference footer PAGE đã duyệt, giữ byte phần/quan hệ nguồn; footer khác giữ nguyên. Số thông thường/không ghép chắc hoặc Word bỏ phần nguồn đều phục hồi. Candidate chỉ đổi phần header PAGE và cờ section/quan hệ/ContentTypes cần thiết, không sửa thân. Đợt17 bảo toàn bitmap toàn ảnh đã giải mã qua hash pixel, mapping và opacity; Image/ImageBrush tương đương có thể so khớp khi Word đổi tên/mã hóa tài nguyên. Ảnh crop/tile/xoay/profile hoặc paint chưa rõ vẫn giữ thủ công; không nhận diện chữ ký. Chạy các nhóm chọn kèm trước, quét lại theo cấu hình hiện tại; giữ một Undo/rollback cả lượt. Hậu kiểm field/section/footer, số thực trên từng trangXPS, ẩn trang1 và nguyên vị trí/chữ/bảng/ảnh/footer trước-sau; không báo đạt chỉ từ codePAGE. Số phải thực sự hiện đủ, đen đục, cùng trục và không bị clip/mask; hậu kiểm giữ paint/độ hiển thị của chữ/hình/footer, chưa rõ thì phục hồi. Giữ nguyên cả run footer chỉ chứa khoảng trắng; hậu kiểm lại các nhóm chữ/phông/căn-khoảng đoạn/Line chọn kèm sau bước PAGE cuối, tiến độ không đổi tổng giữa các nhóm. Chưa có runtime Office2021 cho nhóm mới.",
            new ReportExample("Văn bản hai trang chưa có số; footer có ghi chú cần giữ ở cả trang đầu.","Sau duyệt: trang1 ẩn số, trang2 hiện2 bằng PAGE trong lề trên; giữ nguyên thân và footer cả hai trang.")),
        new("M01","Khổ giấy và lề",CapabilityMode.Manual,"Nhà nước/Đảng",
            "C32 đã sửa trong phạm vi dọc thông thường xác minh. Trang ngang/lề đối xứng, nhiều section, hình/Shape/field hoặc bố cục chưa chắc còn cảnh báo thủ công; không tự đổi hướng hoặc bỏ thành phần.",
            new ReportExample("Section trang ngang có bảng rộng và lề đối xứng.","Đối chiếu loại tài liệu/ngoại lệ và chỉnh trong Word; chưa tự đổi hướng trang hoặc lề trong/ngoài.")),
        new("M02","Khác hàng hoặc vị trí dọc số/ngày",CapabilityMode.Manual,"Khi đo được mốc XPS",
            "Chưa tự dịch theo chiều dọc hoặc làm số và ngày cùng hàng.",
            new ReportExample("Dòng Số: 01/BC-ABC cao hơn dòng địa danh/ngày 12 pt.","Cảnh báo khi đo được mốc; chưa tự dịch dọc để làm hai dòng cùng hàng.")),
        new("M03","Cách viết trích yếu hoặc tên loại chưa đủ chứng cứ",CapabilityMode.Manual,"Khối đã nhận diện",
            "Tên loại chỉ chưa viết hoa nhưng đủ chứng cứ được đề xuất theo C24. Tên loại chưa rõ hoặc trích yếu toàn chữ hoa giữ thủ công để bảo toàn tên riêng/mã; phần phông có gợi ý riêng đủ điều kiện.",
