        new("0.1.51","Thêm ngữ cảnh cấu trúc cho thứ tự mục gõ tay và dấu đầu dòng đơn trong từng mục cha; bằng chứng XML, sửa nhóm/rollback và ví dụ C20/C21."),
        new("0.1.52","Rút tooltip còn Lỗi — Căn cứ — Cách xử lý; nêu đúng vị trí và nội dung quy định, phân biệt cấu hình người dùng; giữ số đo/ngữ cảnh đầy đủ trong Chi tiết lỗi."),
        new("0.1.53","Chọn nhiều nhóm một lượt: sửa chữ/phông, đo lại, căn giữa và Line theo đúng mục đã chọn; một Undo, hậu kiểm nét/phông/vị trí và rollback toàn bộ nếu bước sau lỗi."),
        new("0.1.54","Nhận diện trích yếu nhiều đoạn/ngắt dòng và Kính gửi căn giữa; tên cơ quan C22, nơi nhận 9b C23 theo NĐ30; tách thông tin phạm vi XML khỏi lỗi dòng đầu, giữ sửa nhóm/rollback."),
        new("0.1.55","Hậu kiểm phông trong lượt nhiều nhóm dùng toàn thân đã xác minh XML, gồm nơi nhận sau đoạn 40; không mở rộng phạm vi đo Line/căn giữa."),
        new("0.1.56","Sửa cảnh báo phông giả ở cơ quan/trích yếu sau chèn Line: proof định dạng riêng cho Line nổi của ứng dụng đã xác minh, không mở sửa chữ qua đối tượng. C20/C21 đủ điều kiện chuyển Bắt buộc sửa theo yêu cầu người dùng; giữ duyệt, kiểm nét XPS, một Undo/rollback."),
        new("0.1.57","Thêm cửa sổ tiến độ độc lập khi sửa: bước hiện tại, số mục hậu kiểm tạm thời, thời gian chờ, đo lại/quét lại/phục hồi; chưa hoàn tất trước quét lại. Mở proof định dạng cho Line trong nhánh tương thích/run gộp, đọc từng ký tự Word khi phông vùng bị trộn; giữ kiểm nét và rollback, chưa xác nhận runtime Office 2021."),
        new("0.1.58","Thêm C24 viết hoa chính xác tên loại văn bản đã nhận diện chắc theo NĐ30 II.5.b; giữ trích yếu, khoảng ngoài tên, phông/căn đoạn, chặn trường/đối tượng/vùng chưa rõ; sửa chung phông, quét lại và một Undo/rollback. Lỗi cơ quan/trích yếu trên .56 vẫn chờ bằng chứng runtime .57 hoặc mới hơn."),
        new("0.1.59","Danh mục đủ 27 tên hành chính/3 bản sao theo NĐ30 PL III.I trang 40; thêm Báo cáo đề xuất/BCĐX theo người dùng, tách nguồn. Dùng chung nhận diện/C24/phông/mốc trích yếu, không áp thể thức gốc cho bản sao; sửa cảnh báo nhầm chữ thường ở QyĐ/CTr/TTr/TrS, giữ mã cơ quan. Có cửa sổ tra cứu và danh mục đầy đủ trong TXT."),
        new("0.1.60","Gom 5 bước sau .59: B01 hoa/thường viết tắt theo tên loại chắc chắn; B02 cảnh báo tên loại/ký hiệu mâu thuẫn, không đoán bên sai; B03 thêm khoảng sau hai chấm; B04 C25 bỏ dấu cách cuối đoạn có điều kiện, giữ kết đoạn/ô; B05 C15 thêm khoảng sau ngoặc đóng trong cụm chữ rõ. Chọn riêng/chung, giữ khoảng chưa chọn, XPS, một Undo/rollback; tổng25/8/1. Bản thử, chưa xác nhận toàn bộ bài Word trên Office 2021."),
        new("0.1.61","Gom B01–B05 sau .60. B01–B03: cụm lặp khác chữ hoa đầu đoạn, dấu câu sau ngoặc, câu cuối một từ. B04: luồng kiểm định dạng chung, gắn dữ liệu vào text, phân biệt đúng/sai/chưa chắc; aggregate → từ → ký tự, giữ cỡ hợp lệ và kiểm từng cỡ sau lưu/Line. B05: chọn đường kẻ tích kèm đúng lỗi cần sửa trước, duyệt rõ; sửa chữ/phông → đo lại → Line, chỉ ghi nếu cần; bỏ đọc CP và đo mốc lặp trong cùng bản xem trước. Giữ XPS, quét mới, một Undo/rollback; tổng25/8/1. Bản thử, chưa xác nhận bài Word Office 2021 hoặc khép phản hồi .56 chỉ bằng CI."),
        new("0.1.62 — đợt tích lũy","B01 sau .61: sửa riêng cỡ sai trong cơ quan 12–13, tên loại/trích yếu/ngày 13–14 đã nhận diện chắc; giữ mỗi cỡ đúng, chữ/kiểu và sửa chung chữ → đo lại → Line. Chụp cỡ nguồn, chuẩn hóa đúng glyph sai, chiếu qua sửa chữ và hậu kiểm từng cỡ sau lưu/Line; sai thì rollback một lượt. B02: mở sửa cỡ hỗn hợp quốc hiệu/tiêu ngữ khi giữ nguyên chữ; dùng cùng writer Range ký tự, bảo toàn cỡ, quyền định dạng qua Line và hậu kiểm sau lưu/Line. Giữ guard khi đồng thời cần thay chữ, Đảng vẫn cỡ15 riêng. B03: viết hoa tên loại cỡ hỗn hợp; đối chiếu phông/cỡ/màu/đậm/nghiêng/gạch chân từng ký tự và căn/thụt đoạn sau lưu/Line, giữ phần chưa chọn và chuẩn hóa đúng phần phông/cỡ đã duyệt. Dùng Range.Case, không thay text cả vùng. B04: mục số gõ tay2–4 cấp, chỉ sửa số cuối dưới mục cha rõ; giữ tiền tố/tab, chặn đổi cha còn tiền tố con hoặc dẫn chiếu đến số cũ/số dự kiến, quét lại và rollback. B05: mở C25 cho khoảng cuối sau chấm phẩy trong câu chữ rõ, giữ dấu/ô trống/phần chưa chọn, hồi quy sửa chung và rollback. Đủ5 hạng mục; kết quả/gói theo đúng commit tại PR/release, không suy có bản tải từ version. Chưa xác nhận runtime Office 2021."),
        new("0.1.63 — đợt tích lũy","B01 sau .62: kiểm/sửa phông, màu và cỡ đoạn văn xuôi thường có ranh giới xác minh, giữ mỗi cỡ đúng và đối chiếu kiểu ký tự/căn đoạn sau lưu/Line. B02: C27 căn đều/thụt đầu dòng văn xuôi chắc, giữ1cm/1,27cm đang đúng và sửa sai về1,27cm, giữ phông/cỡ/khoảng đoạn/giãn dòng sau lưu/Line; sửa riêng/chung và rollback. B03: C28 khoảng giữa hai đoạn liền nhau cùng trang, chỉ kết luận khi cả hai khoảng đặt chưa thể đạt6pt, sau đoạn trước6pt và giữ trước đoạn sau; B04: C29 Double/Multiple ngoài1–1,5 vềSingle, Exactly/AtLeast chờ đo. Tách đề xuất, ghép cùng C26/C27/chữ/Line theo snapshot bất biến, kiểm ngữ cảnh và đoạn kế sau lưu/Line, giữ phần chưa chọn, một Undo/rollback. B05: văn bản có tên loại không Kính gửi, cần hai đoạn mở đầu văn xuôi có XML căn đều/thụt1cm hoặc1,27cm và dữ liệu kiểu chắc; không dùng chữ nhấn mạnh/không rõ làm mốc. Hai mốc ngắn sau xóa lặp vẫn giữ vai trò, không làm mất lỗi chưa chọn phía sau. Chưa mở toàn bộ thân bài hoặc mọi cách giãn đoạn; đủ5 bước, gói/kết quả theo commit tại PR/release, chưa xác nhận Word/Office 2021."),
        new("0.1.64 — đợt tích lũy","B01 sau .63: C26 sửa phông/màu/cỡ đoạn có nhấn mạnh, giữ đậm/nghiêng/gạch chân theo từng glyph; cỡ đúng và cả cỡ ở khoảng trắng không bị ép lại. Source snapshot đoạn và kiểu/cỡ bắt buộc, hậu kiểm sau lưu/Line; sửa riêng/chung chữ, một Undo/rollback. Dùng proof kiểu đầy đủ thay lượt đọc cỡ riêng trùng, không bỏ hậu kiểm. B02 mở C27–C29 cho đoạn văn thường có từ nhấn mạnh xen chữ thường đứng, giữ từng kiểu/cỡ/gạch chân; kiểm sửa riêng từng thuộc tính/chung bốn nhóm với chữ/Line, snapshot đoạn kế, stale/drift/quét lại/rollback/một Undo/lưu-mở. Đoạn toàn đậm/nghiêng hoặc không chắc chưa sửa bố cục; hai mốc không Kính gửi vẫn không nhấn mạnh. B03: dùng một snapshot/nhận diện thân bài cho C26–C29 trong mỗi lần quét, thay ba lượt trùng; vẫn giữ riêng từng chính sách, đúng thứ tự lỗi, đoạn liền kề và mọi quét mới/hậu kiểm sau sửa. Không tái dùng qua sửa/lưu/Line hoặc coi quan sát tạm là quyền sửa. B04 thêm C30 xóa khoảng trắng sát trong ngoặc kép cong chứa lời văn rõ, giữ dấu/chữ/kiểu/cỡ và phía chưa chọn; cặp rỗng giữ ô trống, unknown/technical/nested ngoài phạm vi; sửa riêng/chung và rollback. B05 mở C30 cho một dấu .?! gắn cuối câu trích dẫn rõ, giữ dấu và từng kiểu/cỡ; chuỗi dấu/viết tắt/ranh giới chưa chắc chưa mở. Đủ năm bước, tổng30 đề xuất/8 thủ công/1 minh họa; gói/kết quả theo đúng commit tại release, chưa có Word runtime Office2021."),
        new("0.1.65 — đợt tích lũy","B01 sau .64: C14 chuẩn hóa khoảng trước/sau dấu phẩy/chấm phẩy ngay sau ngoặc kép cong đã đối chiếu; giữ quote/nội dung/kiểu/cỡ và mép trong chưa chọn. C30 riêng giữ lỗi dấu câu ngoài còn tích được; chọn chung lỗi chữ/phông/bốn nhóm thân bài/Line có quét và proof nguồn/glyph. Cần hai từ trước, ít nhất hai từ trong và từ phải rõ; mixed/nested/unbalanced/numeric/technical/header/unknown ngoài phạm vi. Parse mỗi loại ngoặc một lần khi cần; không thêm COM/XPS hoặc giảm hậu kiểm/Undo/rollback. B02 mở C30 thêm một dấu cách ASCII sau quote đóng trong ngữ cảnh chữ hai phía rõ, giữ mép trong/chữ/kiểu và quote gốc. C15/C30 dùng cùng gate ngữ cảnh sau cặp; parser/cặp và permission riêng, chặn số/mã/câu kết dấu/unknown. Payload chỉ thêm sau đúng mốc ”, chọn từng mép/nhóm/all và ghép cùng phông/chữ/Line vẫn giữ proof/rollback. B03 thêm khoảng trước dấu mở ngoặc tròn/kép khi đủ ngữ cảnh, giữ lỗi trong/ngoài độc lập và C14 sửa cùng lượt. B04 hỗ trợ quote thẳng cho C30/C14/ô trống, giữ nguyên loại dấu; parser cân bằng dùng chung, không trộn họ dấu. B05 giữ một dấu .?! cuối câu trong ngoặc tròn và khoảng mép, đồng thời giữ lỗi dấu câu trong đoạn còn tìm được sau sửa. Gom B03–B05 cùng lượt theo yêu cầu tiến độ, kiểm72 tổ hợp trước/trong/sau, nhiều nhóm/phông/nét và rollback; đủ5 bước sau .64, tổng30/8/1. Gói/kết quả theo commit tại release, chưa có Word runtime Office2021."),
        new("0.1.67 — mốc trước tối ưu tốc độ","Đóng gói theo yêu cầu người dùng từ mã 0.1.65 tại 56891d501a32f183ba6154e9a5829b2cd65c34e4; giữ nguyên thuật toán kiểm/sửa, dữ liệu trong bảng, Preview Word/XPS, hậu kiểm, một Undo và rollback. Chỉ cập nhật phiên bản, tài liệu và mốc báo cáo; chưa áp dụng phương án tối ưu đọc DOCX/COM hoặc cache. Giữ ZIP/tag/source của mốc này để quay lại nếu thử nghiệm sau không đạt. Tổng30 đề xuất/8 thủ công/1 minh họa không đổi; kết quả kiểm đúng commit tại release, chưa xác nhận runtime Office2021."),
        new("0.1.68 — thử nghiệm đọc nhanh","Từ mốc .67 giữ riêng để quay lại. Dùng chung snapshot WordOpenXML hiện tại cho proof chữ/outline/bảng; vùng format trộn thử đọc theo run nhưng vẫn kiểm CP/chữ và Font Word thật. Chưa đủ chứng cứ thì quay lại Words/Characters; không dùng kết quả một phần hoặc mở rộng quyền sửa. Menu Kiểm tra có bật/tắt và quét lại, log số đo từng chặng/run/từ/ký tự. Giữ đầy đủ bảng, Preview Word/XPS, nét thật, một Undo và rollback. Chưa đổi luật, tổng30/8/1; benchmark chỉ đo XML, CI không chạy Word/Office2021, chưa kết luận nhanh toàn bộ."),
        new("0.1.69 — giảm trao đổi Word/COM và lập chỉ mục Preview","Sau phản hồi .68 tăng tốc ít: thử duyệt đoạn tuần tự có kiểm đủ/CP, đọc gộp phông và thuộc tính đoạn chỉ khi Word xác nhận đồng nhất, giữ Word riêng qua các lần mở; lỗi/unknown có fallback. Dùng chỉ mục chữ cho cùng XPS và xóa khi đổi tài liệu; giữ ngữ cảnh duy nhất/khoảng trắng. Hiện thời gian mở/tổng và counters. Mô hình16 đoạn giảm getter phông80→5, đoạn160→10; không phải tốc độ thực Word. Giữ đầy đủ bảng/Preview Word/XPS, nguồn, editor, nét thật, hậu kiểm, một Undo và rollback; mốc .67/.68 còn nguyên. Tổng30/8/1 không đổi, chưa xác nhận Office2021 hoặc tốc độ toàn phiên."),
        new("0.1.70 — bản thử tích lũy","B01 giữ bộ đọc cũ mặc định theo số đo người dùng, backend và checkbox cùng tắt thử nghiệm. Người dùng yêu cầu dừng tối ưu đọc, ưu tiên thể thức → lỗi chữ cơ bản/khoảng trắng/dấu câu/lặp → ngữ cảnh/thư viện sau cùng. B02 thêm C31: phông/màu/cỡ/đứng/đậm khối ký cuối trong bảng có Nơi nhận/Lưu đối diện, vai trò chức vụ và họ tên riêng; giữ13/14 từng glyph, tên/cấp bậc/ngắt dòng/gạch chân/căn-khoảng đoạn/ảnh chữ ký. Không đoán từ dữ liệu unknown hoặc tự đổi hoa-thường/thẩm quyền; kiểm riêng/chung nhóm, stale, hậu kiểm nguồn/kiểu sau Line/lưu, một Undo/rollback. Có bài Word với ảnh mẫu để chạy riêng; CI không chạy Word. B03 thêm C32 sửa A4 và lề sai của một section dọc đơn giản, candidate chỉ đổi pgSz/pgMar; giữ chữ/bảng/kiểu/phần ZIP khác, lề hợp lệ, kiểm khổ XPS. Trang trước rồi quét/đo lại các nhóm chọn kèm, giữ một Undo/rollback toàn lượt; vùng đặc biệt vẫn thủ công. B04 thêm C33 số trang/PAGE với scope một section/header trống hoặc PAGE-only; giữ footer khi ẩn trang1, cỡ đúng/đậm/gạch chân, thân/bảng/ảnh và một Undo/rollback; kiểm số thậtXPS và vị trí nội dung, chưa có Word runtime. B05 rà và sửa phối hợp toàn lượt: giữ run footer chỉ chứa khoảng trắng trong Flat OPC, điều kiện trang dùng full Document XML, hậu kiểm chữ/phông/cỡ/căn-khoảng đoạn/nét Line sau giai đoạn cuối và tiến độ dùng chung tổng. Có mẫu bảy mục cùng lượt, lỗi ba giai đoạn/Undo/lưu-mở; chưa chạy Word thực. Tổng33 đề xuất/8 thủ công/1 minh họa; chuẩn bị gói Windows sau năm đợt. Số kiểm/commit/run của đúng gói nằm trong build-checks.json và báo cáo TXT đi kèm; chưa có xác nhận Office2021 cho bước mới."),
        new("0.1.71 — kiểm Word theo bộ đọc đã chọn","Log phản hồi ghi0.1.69, Word16.0 Build16.0.20326: IOException0x80070020 tại File.ReadAllBytes checkpoint đang mở, trước bước so sánh; cùng mã còn ở0.1.70. Sửa bằng handle chỉ đọc chia sẻ ReadWrite/Delete để băm đầy đủ, giữ so byte trước/sau; exclusive/missing/byte đổi vẫn lỗi. Bước kiểm khóa file bắt buộc ở cả hai chế độ, không thể bị che bởi việc tắt thử nghiệm. Kiểm Windows tái hiện handle ghi của Word và xác minh không đổi dữ liệu/position/save time. Bài kiểm cũ luôn ép thử nghiệm dù đang tắt. Bản sửa chạy toàn bộ bài chức năng bằng bộ đọc đang chọn; mặc định cũ, ghi NOT_RUN cho thử nghiệm, kết quả chỉ áp dụng phạm vi đó. Nếu bật thử nghiệm thì so sánh vẫn bắt buộc, chạy sau bài chức năng và sai khác vẫn FAIL nghiêm ngặt. Thêm MODE/SCOPE, thông báo ngoại lệ, pha đọc/đo và hai snapshot JSON cùng đường dẫn trường khác nhau; chưa nới số đo hoặc sửa thuật toán đọc. Giữ bảng/Preview/nét XPS, rollback và Undo. Tổng33/8/1; chưa có xác nhận Office2021 chạy đạt bản sửa; nguyên nhân lần phản hồi đã xác định là khóa file, chưa phải sai khác hai bộ đọc."),
        new("0.1.72 — Line tương thích Word", "Phản hồi 0.1.71 đã qua khóa checkpoint và Agency, dừng trước Subject vì thiếu đề xuất. DOCX thực có cặp DrawingML/VML; inventory cũ coi nhánh dự phòng là đối tượng chưa ghép, editor cũ đếm đôi marker. Nhận một cặp có identity/namespace/cấu trúc và đầu mút khớp là một Line; cập nhật cả cặp một lần, giữ run chữ và part khác, từ chối nhánh lạ. Vẫn kiểm nét XPS và bù tọa độ/rollback/Undo. Bài kiểm lưu checkpoint chỉ đọc, XPS và JSON trước từng role; thiếu đề xuất vẫn FAIL có lý do, không bỏ qua Single. Đã kiểm gói người dùng cục bộ và regression sinh tương đương; CI không có Word, chưa xác nhận Office thực chạy đạt 0.1.72. Danh mục 33/8/1 và bộ đọc cũ giữ nguyên."),
        new("0.1.73 — nhãn Line đã bù vị trí", "Phản hồi 0.1.72 tại Subject: mốc/đo chắc, nét Agency đúng XPS nhưng VML alt được Word ghép Title ý định và Description marker; phép nhận cặp trước chỉ nhận Description đơn. Thêm đúng dạng ghép khi khớp toàn bộ Title hợp lệ và marker cùng đối tượng; không dò substring, không bỏ guard endpoint/cấu trúc/XPS hoặc rollback/Undo. Tái hiện bằng checkpoint đúng bước lỗi, thêm regression nhãn ghép sau bù tọa độ, nhãn sai/thiếu/nhãn lạ và đầu mút làm tròn. Candidate giữ nguồn/chữ/bảng/định dạng/part khác; không đưa file người dùng vào repo/gói. Danh mục 33/8/1, bộ đọc cũ và ưu tiên thể thức giữ nguyên. CI không chạy Word; chưa xác nhận toàn bài Office thực đạt 0.1.73."),
        new("Đợt thể thức 05 — nét duy nhất và đủ nét", "Mã phát triển 0.1.74, chưa đóng gói. Tái hiện trên 0.1.73: Find lấy nét đầu giữa hai nét chồng; bù vị trí tiếp tục khi mất nét nền; một nét được tính cho hai yêu cầu giữ. Sửa nhận duy nhất, ghép từng lần xuất hiện và kiểm chung nét giữ/Line chọn, dừng bù khi mất nền, báo thủ công cả khi có lịch sử sửa. Kiểm thứ tự XPS/dung sai giao nhau, số lần xuất hiện, WPF hai Path và rollback muộn. Giữ dung sai, luật, DOCX/bảng/chữ, nhánh tương thích, Undo, bộ đọc cũ và danh mục 33/8/1. Kết quả đúng commit xem CI/PR; CI không chạy Word, chưa xác nhận toàn bộ Office thực. Gói gần nhất vẫn 0.1.73, giữ nhịp tích lũy trước đóng gói."),
        new("Đợt thể thức06 — nét thực sự được vẽ", "Mã 0.1.74 chưa đóng gói, hai cụm sau0.1.73. Kiểm âm tính WPF trên mã đợt05 tái hiện nét dưới ancestor opacity0, bút trong suốt, ngoài clip và Fill rỗng đều bị đếm. Phân biệt nét được vẽ/không vẽ/chưa xác minh; xét Path và ancestor, stroke/fill/fill rule, clip thật/layout/trang và transform. Bị cắt một phần hoặc bút/mask chưa rõ thì thủ công; hậu kiểm từ chối và phục hồi, không suy thiếu để tạo thêm. Giữ chữ nhật mảnh và các ca hợp lệ, không nới dung sai Line hoặc sửa DOCX/bảng/chữ/Undo. Kết quả đúng commit xem CI/PR, CI không chạy Word thực; danh mục33/8/1 và bộ đọc cũ giữ nguyên."),
        new("Đợt thể thức07 — mốc chữ hiển thị đầy đủ", "Mã0.1.74 đang tích lũy ba cụm, chưa đóng gói. Kiểm âm tính trên đợt06 tái hiện sáu trường hợp chữ ẩn/trong suốt/bị cắt/ngoài trang/xoay/dòng đơnẩn vẫn có số đo. Phép đo tham chiếu và dòng hành chính cùng yêu cầu glyph hiện đủ, fill/opacity/mask và clip đã chứng minh, trục dương/thẳng hàng; kiểm mực nhô ngoài advance box và khung tọa độ. Tách proof dùng chung với nét, giữ bounding highlight riêng, không bỏ glyph khỏi chỉ mục hoặc đoán CP; một run thiếu bằng chứng không biến phần còn lại thành mốc ngắn. Kiểm phối hợp/rollback và các nét đợt06 vẫn bắt buộc. Giữ danh mục33/8/1, bộ đọc cũ, DOCX/bảng/chữ/Undo; CI không chạy Word thực, kết quả đúng commit xem PR."),
        new("Đợt thể thức08 — dòng cuối theo đường chân chữ", "Mã0.1.74 đang tích lũy bốn cụm, chưa đóng gói. Tái hiện WPF trên đợt07: cỡ chữ khác làm mất phần đầu mốc và hàng sát bị gộp theo đáy hộp. Gom baseline theo dung sai nửa point, giữ trọn các run cùng hàng, chọn hàng cuối có thứ tự xuống trang và vùng đo tách rõ. Hàng chồng, chữ nâng/hạ hoặc đảo/quay lại chuyển thủ công; dòng hành chính vẫn đúng một hàng. Kiểm nhiều cỡ/chọn hàng sau, đề xuất Line, lịch sử và rollback muộn. Giữ glyph proof, DOCX/bảng/chữ/Undo, luật Line, bộ đọc cũ và danh mục33/8/1. CI không chạy Word thực; kết quả đúng commit xem PR."),
        new("0.1.74 — năm cụm kiểm thể thức", "Tích lũy đợt05–09: nét duy nhất/đủ số lần, nét thực được vẽ và clip, mốc chữ hiển thị trọn, dòng cuối theo baseline đủ mọi cỡ chữ; thêm bằng chứng WordOpenXML/range hiện tại cùng lần đọc khi bài kiểm mẫu không khớp. Bằng chứng có vòng4file mỗi bộ đọc, không bật ở tài liệu thường, không Save/close hoặc đổi quyền sửa. Tái chạy phép đối chiếu từ JSON phải giữ đúng lỗi/quyền; giữ toàn bộ kiểm định dạng và rollback tích lũy. Danh mục33/8/1, bộ đọc cũ mặc định, dừng tối ưu tốc độ. Gói thử có số kiểm/commit/run thực trong build-checks.json/TXT; CI không chạy Word và chưa xác nhận toàn bài Office thực PASS."),
        new("Đợt thể thức10 — khối ký sau đoạn40", "Mã phát triển0.1.75 chưa đóng gói. Tái hiện mã0.1.74: XML hiện tại nhận2 vai trò nhưng bộ chọn quan sát trả0 khi khối ký vượt giới hạn40 đoạn đọc bảng native. C31 dùng vai trò bảng cuối đã khớp XML/range, giữ đúng nhóm tên/chức vụ và quyền sửa từng dòng; không tạo Page/InTable hoặc mở rộng geometry. Kiểm các ranh giới đoạn, hai đường XML, ngắt mềm, thiếu quyền/mismatch; Windows gọi observer thật với COM giả và DOCX mẫu ngắn/dài có schema/ảnh. Bài Office mới chạy thêm sau60 đoạn, vẫn sửa riêng/chung, rollback/Undo/lưu-mở; CI chỉ biên dịch, chưa xác nhận Word thực PASS. Danh mục33/8/1, bộ đọc cũ, gói0.1.74 và main/tag cũ giữ nguyên; tiếp tục tích lũy trước gói mới."),
        new("Đợt thể thức11 — ảnh inline trong khối ký", "Mã0.1.75 tích lũy hai cụm, chưa đóng gói. Tái hiện đợt10: ảnh trước tên tạo Word object CP nhưng XML bỏ drawing, dừng XML-TEXT và mất đủ nhóm ký. So một ảnh nhúng inline rõ cấu trúc với ký tự Word thực, giữ nguyên Start/End và đóng khi thiếu/thừa/sai; đoạn ảnh không có quyền sửa chữ/phông. C31 bỏ qua riêng đoạn một ảnh không đánh số/style lạ, vẫn đủ vai trò/quyền của tên và chức vụ. Ảnh giữa chữ giữ cả đoạn thủ công; các đoạn sau khớp độc lập được tiếp tục. Không biến ảnh thành Line hoặc bằng chứng XPS. Kiểm Core và observer/schema/ảnh trên mẫu ngắn/dài, ảnh trước/sau tên, inventory Line; mở rộng bài Office4mẫu với rollback/Undo/lưu-mở/giữ ảnh. CI không chạy Word; chưa xác nhận toàn bài thực PASS. Giữ33/8/1, bộ đọc cũ, gói0.1.74/main/tag cũ và dừng tối ưu tốc độ."),
        new("Đợt thể thức12 — chỗ ký tay80pt", "Theo yêu cầu người dùng28/10/2026: ưu tiên chỗ trống in rồi ký tay, dừng mở rộng ảnh chữ ký. Mã0.1.75 tích lũy ba cụm; thêm lệnh chủ động Kiểm tra → Chừa chỗ ký tay (80 pt) ở khối ký bảng cuối đã chứng minh, vùng trống không ảnh. Đo XPS cả Enter sẵn, giữ vùng đã đủ; phản hồi có giới hạn đến80±3pt trên trang hiện tại. Chỉ đổi khoảng trước họ tên, giữ chữ/phông/đoạn/phần khác; kiểm gói XML, lưu/mở lại, một Undo/rollback muộn.80pt là thiết lập người dùng, không phải căn cứ NĐ30. Kiểm Core/COM giả/XPS/schema và bài Office không ảnh0/2Enter; CI chỉ biên dịch Word scenario, chưa runtime PASS. Giữ33/8/1, bộ đọc cũ, gói0.1.74/main/tag cũ và dừng tốc độ; chưa ZIP mới.")
,
        new("Đợt thể thức 13 — nguồn spacing và phạm vi kiểm", "Tái hiện quyền sửa C28/C29 vẫn mở khi nguồn XML beforeLines khác 0. Giữ nguồn direct/style/default, chặn đơn vị dòng và frame/border/section/hướng chữ/spacing chưa rõ; giữ quyền chữ/phông độc lập. Nêu số đoạn còn phần spacing chưa kiểm, kể cả Exactly/AtLeast; không dùng khoảng mực XPS làm khoảng đoạn. Kiểm context của lựa chọn cũ và hậu kiểm sau sửa. Chi tiết FORMAT-BATCH-13.md; CI không chạy Word."),
        new("Đợt thể thức 14 — kiểm từng nhóm Word", "Thêm Kiểm tra → Kiểm tra từng nhóm Word… với sáu nhóm độc lập trên mẫu và phiên Word riêng, luôn dùng bộ đọc cũ. Lỗi mở là NOT_RUN, lỗi kiểm/đóng là FAIL, ghi từng kết quả trước nhóm sau; chỉ tất cả nhóm đã chọn đạt mới SELECTED_PASS, không thay kết quả bài toàn bộ. Mẫu spacing tạo trực tiếp không đợi bài phông/Subject. Kiểm tổng hợp/lỗi kép/ghi báo cáo, schema và scope; chưa chạy Word thực."),
        new("0.1.75 — năm cụm và kế hoạch hoàn thiện", "Tích lũy đợt 10–14: khối ký cuối tài liệu dài, proof ảnh inline đã có, chỗ ký tay 80 pt theo yêu cầu, nguồn spacing và coverage, kiểm Word theo nhóm độc lập. Phân tích phần thiếu trong REMAINING-WORK.md: độ phủ chung, Exactly/AtLeast, trang/section/PAGE, vị trí dọc số-ngày, cấu trúc lạ và dữ liệu chính tả. Giữ danh mục 33/8/1, bộ đọc cũ, dừng tốc độ và mở rộng ảnh chữ ký. Số kiểm/commit/gói thực lấy từ build-checks.json; CI không chạy Word. Chưa xác nhận bài toàn bộ Office thực PASS.")
,
        new("Đợt thể thức 15 — phạm vi của lần quét", "Mã 0.1.76. Sổ phạm vi bất biến cho 33 nhóm: không áp dụng, chưa nhận diện, thiếu dữ liệu, một phần, đã quan sát và chờ bản xem trước. Đếm cảnh báo riêng; quét 0 cảnh báo không thành chứng nhận toàn tài liệu. Reset khi mở/quét/lỗi; C11/C12 lấy kết quả đo thật, C33 chờ chữ thực sự hiển thị. Cửa sổ chỉ đọc và sao chép báo cáo không chứa nội dung/CP tài liệu; chưa kiểm đủ vẫn nêu rõ. Giữ nguyên quyền sửa. Chi tiết FORMAT-BATCH-15.md."),
        new("Đợt thể thức 16 — số trang được vẽ thật", "Mã 0.1.76 tích lũy hai cụm sau 0.1.75. Hậu kiểm PAGE không chấp nhận số bị ẩn/mờ/cắt/mask chưa rõ, xoay/lật hoặc ngoài trang; xét effective opacity, clip và hộp mực chữ. Không bỏ số sai vị trí khỏi kiểm trang đầu vì ngoài dải tâm đoán trước. Giữ paint/opacity/font của nội dung và footer ngoài lề trên; không giữ được bằng chứng thì phục hồi. Kiểm WPF chữ/hình/footer và rollback; CI không chạy Word. Phạm vi được mở thêm có điều kiện ở đợt17–19; nhiều section và Exactly/AtLeast còn thủ công. Chi tiết FORMAT-BATCH-16.md."),
        new("Đợt thể thức 17 — bảo toàn bitmap khi sửa PAGE", "Đối chiếu pixel Pbgra32 đã giải mã, toàn khung, opacity và cách vẽ; giữ ảnh khi XPS đổi tên/mã hóa tài nguyên. Chưa chứng minh mapping/crop/tile/profile thì phục hồi; không mở rộng nhận diện chữ ký. Chi tiết FORMAT-BATCH-17.md."),
        new("Đợt thể thức 18 — PAGE đơn thuần ở chân trang", "Chuyển nguồn PAGE-only rõ của một section, sốẢRập từ1, tối đa9trang lên header. Xác nhận số nguồn duy nhất trên từng trang XPS, chỉ bỏ reference đã duyệt và giữ phần/quan hệ nguồn. Giữ nội dung khác, kiểm lại sau lưu; một Undo/rollback. Chi tiết FORMAT-BATCH-18.md."),
        new("Đợt thể thức 19 — khổ/lề với đầu-cuối trang trống", "Chứng minh header/footer trống bằng quan hệ, style/default và cấu trúc; giữ nguyên các phần ZIP, đối chiếu lại XML cùng khổ và toàn bộ vùng chữ/mực/nét XPS sau đổi trang và cuối lượt. Một Undo/rollback, chưa mở nhiều section/trang ngang. Chi tiết FORMAT-BATCH-19.md."),
        new("Đợt thể thức 20 — PAGE nhiều chữ số", "Mã phát triển0.1.77: nguồn PAGE-only tới10.000trang, ghép số bị XPS tách cụm theo dòng nền/khung/kiểu, không lấy chuỗi con hoặc cụm chồng/lệch. Bảo toàn nội dung khác và kiểm số dư sau sửa; thêm bài Word từ10trang độc lập. Chưa Word thực PASS hoặc ZIP mới. Chi tiết FORMAT-BATCH-20.md."),
        new("Đợt thể thức 21 — toàn cụm PAGE đầu trang", "Hậu kiểm một cụm số duy nhất, cùng dòng nền và chiều cao, không chồng/cách xa; không nối chữ số rời chỉ để ra giá trị đúng. Giữ phông/cỡ/đen/đứng, vị trí và trang đầu. Chi tiết FORMAT-BATCH-21.md."),
        new("Đợt thể thức 22 — nền tảng bản sao Word cô lập", "Mã phát triển0.1.77, chưa đóng gói. Sao toàn bộ Document.WordOpenXML/Flat OPC gồm XML, nhị phân và quan hệ; giữ namespace, chặn phần thiếu/trùng/không rõ và không ghi đè nguồn. Đối chiếu toàn XPS gồm trang, glyph/phông/advance/cluster/baseline, paint, ảnh, hình học nét và thứ tự vẽ trước hiệu chuẩn. Bài kiểm Word riêng cho Exactly/AtLeast mở bản sao chỉ đọc trong phiên mới, tắt macro/cập nhật liên kết, kiểm nguồn/Undo và cleanup. Chưa chạy Word thực; chưa hiệu chuẩn Single/1,5 hoặc mở quyền sửa C28/C29. Chi tiết FORMAT-BATCH-22.md."),
        new("Đợt thể thức 23 — các gói thử spacing gắn nguồn", "Tạo bốn bản thử Single, 1,5, bỏ khoảng và mốc khoảng sau6pt; chỉ đổi thuộc tính đã định của đoạn/cặp liền nhau. Kiểm nguồn/hash, style/context/section, mọi part/ảnh/quan hệ và schema; nguồn không đổi. Chưa cấp quyền sửa C28/C29. Chi tiết FORMAT-BATCH-23-26.md."),
        new("Đợt thể thức 24 — vector baseline và mốc khoảng đoạn", "So toàn vector Single/1,5; chặn reflow, đổi phông/glyph/trang hoặc dịch phần chưa chọn. Khoảng đoạn so với trial6pt cùng bối cảnh, không lấy chênh lệch với0 so trực tiếp6pt. Giữ paint/ảnh/nét và chặn che chữ chưa rõ. Đây là bằng chứng tổng hợp và mã đo, chưa Word thực PASS."),
        new("Đợt thể thức 25 — nguồn xem trước và tài nguyên Word", "Dùng lại XPS hiện tại gắn full XML trước/sau, không xuất lại tài liệu người dùng khi đo. Các bản thử chỉ đọc trong phiên Word riêng; thử mọi Close/Release/Quit và khôi phục từng tùy chọn độc lập, giữ bản phục hồi nếu cleanup lỗi. Khoảng đoạn chưa đủ bằng chứng không che phép đo dòng độc lập."),
        new("Đợt thể thức 26 — đo thử theo yêu cầu", "Thêm menu Đo thử giãn dòng và khoảng đoạn, chọn đoạn và xem số đo/giới hạn; không tự chạy lúc mở cửa sổ hoặc sửa tài liệu. Xóa kết quả cũ khi đổi đoạn/lỗi, không đưa chữ tài liệu vào báo cáo. Thêm nhóm kiểm Word độc lập, tổng11nhóm; chưa chạy Word thực. Giữ33/8/1, bộ đọc cũ, khoảng ký tay80pt và chưa xuất ZIP mới."),
        new("Đợt 27 — bảo toàn chữ trong đường dẫn và mã", "Khắc phục nguy cơ gộp dấu cách hoặc xóa cụm lặp thuộc tên tệp/đường dẫn/literal. Nhận diện dạng kỹ thuật rõ, chuyển gợi ý chữ trong cả dòng sang thủ công; không coi mọi dấu / là mã, văn xuôi thông thường giữ luật cũ. Không thêm từ điển hoặc suy ngữ cảnh. Chi tiết FORMAT-BATCH-27-29.md."),
        new("Đợt 28 — lỗi đo có nguyên nhân và hướng xử lý", "Phân biệt preview thiếu/cũ, phạm vi chưa hỗ trợ, lỗi thao tác, toàn vẹn, cleanup và nguồn đổi. Chỉ thiếu bằng chứng được khai báo mới trở thành kết quả khoảng đoạn chưa đo; lỗi bản thử/COM/I/O/cleanup không bị nuốt. Giao diện không hiện nội dung từ exception và bác trạng thái trái số đo."),
        new("Đợt 29 — kiểm Word độc lập cho sửa chữ", "Nhóm kiểm thứ12 dùng mẫu văn xuôi xen đường dẫn/tên tệp/URL, sửa riêng/chung, lỗi muộn, một Undo, lưu/mở lại, giữ nguồn và đậm/gạch chân. Có kiểm schema/giữ part và quyền chọn trước CI; kịch bản Word chưa chạy thật. Giữ quyền tự sửa Exactly/AtLeast, main, tag và gói cũ."),
        new("Đợt 30 — toàn vẹn và định dạng tên tệp Office", "Manifest DOCX có XML hỏng phải thành lỗi toàn vẹn, không biến thành thiếu bằng chứng. Giữ khoảng/lặp trong tên .docm/.dotx/.rtf/.odt và các dạng template/macro/OpenDocument đã nhận diện, kể cả dấu Unicode tổ hợp."),
        new("Đợt 31 — chạy kiểm Word và đóng phiên nghiêm ngặt", "Lệnh --word-check chọn rõ nhóm bằng mẫu giả, không nhận tài liệu người dùng; mã0 chỉ đủ mọi nhóm PASS,1 là FAIL/NOT_RUN và2 là lệnh sai. Báo cáo ghi module Desktop/Core để phân biệt bản cùng version. Lỗi Close/Quit/Release, lịch sử đóng lỗi hoặc checkpoint chưa chắc chặn PASS và giữ phục hồi; chỉ tác động phiên kiểm riêng."),
        new("Đợt 32 — bản thử Windows có bằng chứng", "Gom thành một artifact Windowsx64 tự chứa runtime, kèm mẫu, hướng dẫn và launcher ba nhóm kiểm. Chạy Core/WPF thực, kiểm metadata trước/sauZIP, toàn bộ file/SHA và EXE từ chối lệnh sai. Artifact preview không ghi đè release/tag; Word thực vẫn cần xác minh, chưa mở quyền sửa Exactly/AtLeast."),
        new("Đợt 33 — chuyển tài liệu có phục hồi", "Mã phát triển 0.1.78 sau bản thử 0.1.77. Chuẩn bị bản mới trước khi đóng phiên cũ; chỉ đổi nguồn, trạng thái và Undo khi Word mở được. Nếu mở thất bại, khôi phục bản làm việc trước đó; lỗi phục hồi giữ bản sao và không xác nhận checkpoint. Kiểm lỗi sao chép/mở/đóng bằng callback và tệp thật; chưa thay bằng kết quả Word thực."),
        new("Đợt 34 — kết quả phục hồi rõ ràng", "Checkpoint không còn suy trạng thái từ tên AggregateException. Giữ lỗi thao tác gốc khi rollback đã thành công; lỗi phục hồi thật có trạng thái riêng và giữ backup. Lỗi dọn tệp không làm mất kết quả mở lại đã xác minh."),
        new("Đợt 35 — giữ chuỗi kỹ thuật còn thiếu", "Gợi ý khoảng trắng và cụm lặp trong lời gọi hàm có chuỗi, đường dẫn tệp ngay dưới thư mục gốc POSIX và email có dấu Unicode tổ hợp chuyển thủ công. Không tự coi mọi dấu ngoặc, dấu nháy hoặc dấu / trong văn xuôi là mã; chưa thêm từ điển/ngữ nghĩa."),
        new("Đợt 36 — dọn tài nguyên và bỏ preview cũ", "Khi quét lỗi, tách trang xem trước cũ khỏi giao diện. Lỗi đóng/xóa XPS không bỏ qua việc đóng phiên Word riêng; lỗi release document không bỏ qua Quit/release application. Thử mọi bước độc lập và giữ nguyên nhân lỗi, chỉ xử lý tài nguyên đã sở hữu. Chưa có ZIP 0.1.78 hoặc xác nhận Word thực.")
    });
    public static IReadOnlyList<string> NextSteps { get; }=Array.AsReadOnly(new[]
    {
        "1. Thể thức và độ ổn định: kiểm tra tổng thể trên Office 2021; xử lý lỗi thực, hoàn thiện nhận diện và phần thể thức còn thiếu theo nguồn. Giữ sửa riêng/nhóm, quét, Undo, lưu/mở, nét thật và rollback.",
        "2. Lỗi chữ cơ bản: mở rộng các quy tắc có thể kiểm chứng về ký tự, khoảng trắng, dấu câu và từ/cụm lặp; bổ sung mẫu, ngoại lệ và kiểm thử. Chưa có từ điển thì không kết luận đã kiểm đầy đủ chính tả tiếng Việt.",
        "3. Sau cùng: ngữ cảnh, ngữ nghĩa và thư viện phục vụ các trường hợp khó; chưa tự suy đoán hoặc viết lại câu trong giai đoạn hiện nay."
    });
    public static IReadOnlyList<ReportPlannedWork> PlannedWork { get; }=Array.AsReadOnly(new ReportPlannedWork[]
    {
        new("P01","Vị trí dọc số/ngày",new ReportExample("Dòng số và dòng ngày lệch hàng 12 pt.","Hoàn thiện nhận diện, căn cứ, phép đo và hậu kiểm trước khi cho phép dịch dọc; hiện chưa có nút tự sửa phần này.")),
        new("P02","Thể thức các vùng còn thiếu",new ReportExample("Chữ ký nằm ngoài bảng cuối văn bản hoặc chức vụ chưa nhận diện chắc dùng Arial màu đỏ.","C31 đã hỗ trợ phông/cỡ khối ký trong phạm vi chắc. Tiếp tục nhận diện các cách bố trí khác trước khi mở quyền sửa; chưa tự áp phông cho toàn bộ thân bài/chữ ký; nơi nhận 9b có phạm vi C23 riêng, văn xuôi thường đủ điều kiện có C26–C29; giãn Exactly/AtLeast, khoảng đoạn bị gộp/auto/grid còn cần đo thêm.")),
        new("P03","Dấu câu ngoài phạm vi hiện tại",new ReportExample("Đã hoàn thành.tiếp tục báo cáo","Nghiên cứu ranh giới câu, chữ hoa/thường, viết tắt và ngoại lệ; C18/C19 cần từ sau viết hoa đầu đủ rõ, chưa sửa ví dụ này hoặc tự viết hoa.")),
        new("P04","Chính tả qua dữ liệu kiểm chứng",new ReportExample("Tôi xẽ gửi báo cáo.","Cần dữ liệu từ và mẫu ngoại lệ trước khi đề xuất xẽ → sẽ; hiện chưa có quy tắc sửa ví dụ này. Chưa coi chương trình là bộ kiểm chính tả đầy đủ.")),
        new("P05","Ngữ cảnh và từ dễ nhầm — làm sau cùng",new ReportExample("Anh ấy giành thời gian đọc sách.","Nghiên cứu ngữ cảnh giành/dành và thư viện sau phần thể thức/lỗi chữ cơ bản; chưa có gợi ý tự động cho ví dụ này."))
    });
    public static int Count(CapabilityMode mode)=>Capabilities.Count(c=>c.Mode==mode);
    public static string Build(string version,DateTimeOffset created,ReportEvidence? evidence=null)
    {
        var text=new StringBuilder();
        void Line(string value="")=>text.AppendLine(value);
        Line("CHÍNH TẢ VIỆT — TIẾN ĐỘ VÀ CHỨC NĂNG");
        Line("Phiên bản: "+version);Line("Tạo lúc: "+created.ToString("yyyy-MM-dd HH:mm zzz",System.Globalization.CultureInfo.InvariantCulture));
        Line("Báo cáo năng lực chương trình; không phải số lỗi đã sửa trong tài liệu đang mở.");
        Line("Trạng thái đã hỗ trợ/chưa tự sửa/dự kiến là tiến độ phát triển, không phải lịch sử sửa tài liệu.");
        Line("Ví dụ dùng dữ liệu giả để minh họa điều kiện; [TAB] là ký hiệu tab. Dấu cách trong ví dụ được giữ nguyên.");
        Line("Các dòng của ví dụ thứ tự mục/dấu đầu dòng thể hiện các đoạn riêng, không ghép chung một đoạn.");Line();
        Line($"TỔNG QUAN: {Count(CapabilityMode.Reviewable)} nhóm có thể đề xuất sửa; {Count(CapabilityMode.Manual)} nhóm chỉ cảnh báo; {Count(CapabilityMode.Demonstration)} quy tắc minh họa.");
        Line("Sửa được khi nhận diện đủ chắc chắn và người dùng duyệt. Không có cảnh báo không đồng nghĩa đúng toàn bộ thể thức/chính tả.");Line();
        Line("KẾT QUẢ KIỂM THỬ ĐI KÈM GÓI");
        if(evidence is not null && evidence.Matches(version))
        {
            Line($"Windows tự động: {evidence.CoreChecks} Core/OpenXML và {evidence.WpfChecks} WPF đạt.");
            Line("Nguồn kết quả: "+evidence.RunUrl);Line("Mã nguồn gói: "+evidence.Commit);
        }
        else Line("Chưa có thông tin kiểm thử đi kèm phù hợp phiên bản; không suy đoán số kiểm tra hoặc trạng thái ĐẠT.");
        Line("CI không có Word; chưa có xác nhận bài Word đúng phiên bản cho toàn bộ chức năng hiện tại trên Office 2021.");
        Line("Mốc người dùng đã xác nhận: sửa ba Line cùng lúc trên .27. Những chức năng sau đó tiếp tục thử nghiệm.");Line();
        foreach(var mode in Enum.GetValues<CapabilityMode>())
        {
            Line(mode switch {CapabilityMode.Reviewable=>"ĐÃ HỖ TRỢ ĐỀ XUẤT SỬA — CẦN DUYỆT",CapabilityMode.Manual=>"CHƯA TỰ SỬA — CHỈ CẢNH BÁO",_=>"QUY TẮC MINH HỌA"});
            foreach(var item in Capabilities.Where(c=>c.Mode==mode))
            {
                Line(item.Id+" — "+item.Name);Line("  Áp dụng: "+item.Scope);Line("  "+item.Detail);
                Line("  Ví dụ: “"+item.Example.Before+"”");
                Line((mode==CapabilityMode.Reviewable?"  Kết quả minh họa khi duyệt sửa: ":mode==CapabilityMode.Manual?"  Hiện tại: ":"  Cần duyệt ngữ cảnh: ")+item.Example.Outcome);
            }
            Line();
        }
        Line("DANH MỤC TÊN LOẠI VÀ CHỮ VIẾT TẮT");
        Line(DocumentTypeCatalog.Citation);
        foreach(var source in Enum.GetValues<DocumentTypeSource>())
        {
            Line(source switch {DocumentTypeSource.DecreeAdministrative=>"27 TÊN LOẠI HÀNH CHÍNH THEO NGHỊ ĐỊNH",DocumentTypeSource.DecreeCopy=>"3 LOẠI BẢN SAO THEO NGHỊ ĐỊNH",_=>"BỔ SUNG THEO YÊU CẦU NGƯỜI DÙNG"});
            foreach(var item in DocumentTypeCatalog.Entries.Where(e=>e.Source==source))Line("  "+item.Name+" — "+item.Abbreviation);
        }
        Line(DocumentTypeCatalog.UserNote);
        Line("Danh mục đầy đủ không có nghĩa đã kiểm mọi mẫu đặc thù. Bản sao có thể thức riêng; chưa tự đổi chữ viết tắt theo tên loại hoặc mã cơ quan. Giữ đúng QyĐ, CTr, TTr, TrS.");Line();
        Line("CHU KỲ PHÁT TRIỂN");
        Line("Gom khoảng 5–10 bước có kiểm thử rồi mới đóng gói Windows; từng bước vẫn cập nhật code và nhật ký. Nội dung đợt sau .59 được ghi tại docs/BATCH-AFTER-0.1.59.md.");Line();
        Line("CÁC NỘI DUNG ĐÃ LÀM");
        foreach(var item in Milestones)Line(item.Version+": "+item.Detail);
        Line();Line("GIỚI HẠN CÒN LẠI");
        Line("Chưa kiểm/sửa đầy đủ tên/mã cơ quan chính thức, toàn bộ thân bài, chữ ký và mọi biến thể nơi nhận, số trang và mọi mẫu riêng. Header/footer/textbox, bảng gộp/lồng, field/control mọi trang còn giới hạn. Track Changes hoặc tài liệu bảo vệ chưa được hỗ trợ.");
        Line("Phần chính tả tiếng Việt đầy đủ chưa hoàn thành. Danh mục có điều kiện không phải kết luận pháp lý hoặc kết quả kiểm tra tài liệu cụ thể.");
        Line();Line("CÁC BƯỚC TIẾP THEO — THEO ƯU TIÊN ĐÃ THỐNG NHẤT");
        foreach(string item in NextSteps)Line(item);
        Line();Line("CÁC VIỆC DỰ KIẾN — CHƯA TRIỂN KHAI SỬA TỰ ĐỘNG");
        Line("Đây là hướng phát triển, không phải danh sách chức năng hiện có hoặc cam kết thời điểm hoàn thành.");
        foreach(var item in PlannedWork)
        {
            Line(item.Id+" — "+item.Name);Line("  Ví dụ: “"+item.Example.Before+"”");
            Line("  Chuẩn bị/nghiên cứu: "+item.Example.Outcome);
        }
        Line();Line("CÁCH KIỂM TRA TỔNG THỂ");
        Line("Với từng nhóm: sửa riêng → sửa nhóm → quét lại → một Undo → lưu bản sao/mở lại. Từ .53 có thể chọn nhiều nhóm cùng lúc: chương trình tự sửa chữ/phông, đo lại, căn giữa và Line theo mục đã chọn; một Undo bỏ cả lượt. Mục chỉ cảnh báo vẫn giữ thủ công. Ghi phiên bản, tên cảnh báo, thao tác và kết quả thực tế khi báo lỗi.");
        return text.ToString();
    }
}
